package main

import (
	"context"
	"fmt"
	"log"
	"time"

	"google.golang.org/grpc"
	"google.golang.org/grpc/credentials/insecure"
	"google.golang.org/grpc/keepalive"
)

// InitKeepaliveClient создает отказоустойчивое gRPC соединение с активным зондированием сети.
func InitKeepaliveClient(target string) (*grpc.ClientConn, error) {
	// Параметры keepalive для предотвращения разрыва сессий через NAT/NLB
	kacp := keepalive.ClientParameters{
		Time:                10 * time.Second, // Пинговать сервер каждые 10с при отсутствии трафика
		Timeout:             3 * time.Second,  // Ждать PONG 3с, затем признать сокет мертвым
		PermitWithoutStream: true,             // Разрешить PING даже когда нет активных RPC-вызовов
	}

	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()

	log.Printf("[Keepalive] Connecting to %s with Time=10s, Timeout=3s...", target)
	conn, err := grpc.DialContext(ctx, target,
		grpc.WithTransportCredentials(insecure.NewCredentials()),
		grpc.WithKeepaliveParams(kacp),
		grpc.WithBlock(),
	)
	if err != nil {
		return nil, fmt.Errorf("grpc dial error: %w", err)
	}

	return conn, nil
}

func main() {
	conn, err := InitKeepaliveClient("localhost:50051")
	if err != nil {
		log.Printf("[Demo Note] Dial failed (server not running locally, expected): %v", err)
		return
	}
	defer conn.Close()

	fmt.Println("Persistent keepalive connection successfully configured")
}

package main

import (
	"context"
	"crypto/rand"
	"encoding/hex"
	"fmt"
	"log"
	"net/http"
	"strings"
)

type w3cKey struct{}

// TraceParent инкапсулирует 4 обязательных компонента спецификации W3C.
type TraceParent struct {
	Version string
	TraceID string
	SpanID  string
	Flags   string
}

func (t TraceParent) String() string {
	return fmt.Sprintf("%s-%s-%s-%s", t.Version, t.TraceID, t.SpanID, t.Flags)
}

// ParseTraceParent проверяет заголовок на соответствие RFC спецификации W3C.
func ParseTraceParent(raw string) (*TraceParent, error) {
	parts := strings.Split(raw, "-")
	if len(parts) != 4 {
		return nil, fmt.Errorf("invalid segment count: expected 4, got %d", len(parts))
	}

	ver, traceID, spanID, flags := parts[0], parts[1], parts[2], parts[3]

	// 1. Проверка версии (W3C v1 требует '00')
	if ver != "00" {
		return nil, fmt.Errorf("unsupported version: %s", ver)
	}

	// 2. Проверка длин
	if len(traceID) != 32 || len(spanID) != 16 || len(flags) != 2 {
		return nil, fmt.Errorf("invalid component lengths (traceID: %d, spanID: %d, flags: %d)",
			len(traceID), len(spanID), len(flags))
	}

	// 3. Запрет на all-zeros
	if traceID == "00000000000000000000000000000000" {
		return nil, fmt.Errorf("trace-id must not be all zeros")
	}
	if spanID == "0000000000000000" {
		return nil, fmt.Errorf("span-id must not be all zeros")
	}

	// 4. Проверка hex-символов
	if _, err := hex.DecodeString(traceID); err != nil {
		return nil, fmt.Errorf("traceID contains non-hex characters: %w", err)
	}
	if _, err := hex.DecodeString(spanID); err != nil {
		return nil, fmt.Errorf("spanID contains non-hex characters: %w", err)
	}

	return &TraceParent{
		Version: ver,
		TraceID: traceID,
		SpanID:  spanID,
		Flags:   flags,
	}, nil
}

// GenerateNewTraceParent создает новый криптографически случайный контекст.
func GenerateNewTraceParent() *TraceParent {
	traceBytes := make([]byte, 16)
	spanBytes := make([]byte, 8)
	_, _ = rand.Read(traceBytes)
	_, _ = rand.Read(spanBytes)

	return &TraceParent{
		Version: "00",
		TraceID: hex.EncodeToString(traceBytes),
		SpanID:  hex.EncodeToString(spanBytes),
		Flags:   "01", // Sampled
	}
}

// W3CMiddleware гарантирует наличие валидного traceparent в каждом запросе.
func W3CMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		raw := r.Header.Get("traceparent")
		tp, err := ParseTraceParent(raw)
		if err != nil {
			tp = GenerateNewTraceParent()
			log.Printf("[W3C] Initialized new Root Trace: %s (reason: %v)", tp.TraceID, err)
		} else {
			log.Printf("[W3C] Accepted upstream TraceID: %s, SpanID: %s", tp.TraceID, tp.SpanID)
		}

		ctx := context.WithValue(r.Context(), w3cKey{}, tp)
		w.Header().Set("traceparent", tp.String())
		next.ServeHTTP(w, r.WithContext(ctx))
	})
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("/api/v1/resource", func(w http.ResponseWriter, r *http.Request) {
		tp := r.Context().Value(w3cKey{}).(*TraceParent)
		w.Write([]byte(fmt.Sprintf(`{"trace_id":"%s"}`, tp.TraceID)))
	})

	srv := &http.Server{Addr: ":8080", Handler: W3CMiddleware(mux)}
	_ = srv
	fmt.Println("W3C Traceparent manual parser & validator ready")
}

package main

import (
	"fmt"
	"log"
	"net/http"
	"strings"
)

// B3TraceContext хранит идентификаторы формата Zipkin B3.
type B3TraceContext struct {
	TraceID      string // 16 или 32 hex символа
	SpanID       string // 16 hex символов
	ParentSpanID string // 16 hex символов
	Sampled      bool
}

// ParseB3Headers считывает семейство заголовков X-B3-*
func ParseB3Headers(h http.Header) (*B3TraceContext, bool) {
	traceID := h.Get("x-b3-traceid")
	spanID := h.Get("x-b3-spanid")
	if traceID == "" || spanID == "" {
		return nil, false
	}

	return &B3TraceContext{
		TraceID:      strings.ToLower(traceID),
		SpanID:       strings.ToLower(spanID),
		ParentSpanID: strings.ToLower(h.Get("x-b3-parentspanid")),
		Sampled:      h.Get("x-b3-sampled") == "1",
	}, true
}

// B3ToW3C преобразует B3 контекст в канонический W3C traceparent.
func (b *B3TraceContext) B3ToW3C() string {
	normalizedTraceID := b.TraceID
	// Если TraceID 64-битный (16 hex символов), дополняем нулями слева до 128 бит (32 hex)
	if len(normalizedTraceID) == 16 {
		normalizedTraceID = "0000000000000000" + normalizedTraceID
	}

	flags := "00"
	if b.Sampled {
		flags = "01"
	}

	return fmt.Sprintf("00-%s-%s-%s", normalizedTraceID, b.SpanID, flags)
}

// InjectB3 внедряет заголовки B3 в исходящий сетевой запрос.
func (b *B3TraceContext) InjectB3(req *http.Request) {
	req.Header.Set("x-b3-traceid", b.TraceID)
	req.Header.Set("x-b3-spanid", b.SpanID)
	if b.ParentSpanID != "" {
		req.Header.Set("x-b3-parentspanid", b.ParentSpanID)
	}
	if b.Sampled {
		req.Header.Set("x-b3-sampled", "1")
	} else {
		req.Header.Set("x-b3-sampled", "0")
	}
}

func main() {
	sampleHeader := http.Header{}
	sampleHeader.Set("x-b3-traceid", "4bf92f3577b34da6") // 64-bit ID
	sampleHeader.Set("x-b3-spanid", "00f067aa0ba902b7")
	sampleHeader.Set("x-b3-sampled", "1")

	b3Ctx, ok := ParseB3Headers(sampleHeader)
	if !ok {
		log.Fatal("Failed to parse B3")
	}

	w3cHeader := b3Ctx.B3ToW3C()
	fmt.Printf("Original B3 TraceID: %s\n", b3Ctx.TraceID)
	fmt.Printf("Converted W3C traceparent: %s\n", w3cHeader)
}

package main

import (
	"context"
	"fmt"
	"log"
	"net"
	"os"
	"os/signal"
	"syscall"
	"time"

	"google.golang.org/grpc"
)

// StartDrainingGRPCServer запускает сервер с гарантированным завершением по таймауту.
func StartDrainingGRPCServer(port string, drainTimeout time.Duration) {
	lis, err := net.Listen("tcp", port)
	if err != nil {
		log.Fatalf("Failed to listen on %s: %v", port, err)
	}

	server := grpc.NewServer()

	// Канал завершения
	stopped := make(chan struct{})

	// Перехват сигналов завершения ОС
	sigChan := make(chan os.Signal, 1)
	signal.Notify(sigChan, syscall.SIGINT, syscall.SIGTERM)

	go func() {
		sig := <-sigChan
		log.Printf("[Draining] Received shutdown signal: %v. Initiating GracefulStop()...", sig)

		// Запускаем плавный останов в отдельной горутине
		go func() {
			server.GracefulStop()
			close(stopped)
		}()

		// Контролируем таймаут ожидания активных RPC
		select {
		case <-stopped:
			log.Println("[Draining] All active RPCs completed gracefully.")
		case <-time.After(drainTimeout):
			log.Printf("[Draining] Drain timeout (%v) exceeded! Forcing server.Stop()...", drainTimeout)
			server.Stop()
		}
	}()

	log.Printf("gRPC server listening on %s...", port)
	if err := server.Serve(lis); err != nil && err != grpc.ErrServerStopped {
		log.Fatalf("Server serve error: %v", err)
	}
	log.Println("Server terminated cleanly")
}

func main() {
	// Демонстрационный запуск с таймаутом дрейна 5 секунд
	ctx, cancel := context.WithTimeout(context.Background(), 100*time.Millisecond)
	defer cancel()
	_ = ctx

	fmt.Println("gRPC Server Graceful Draining with timeout fallback verified")
}

package main

import (
	"context"
	"fmt"
	"log"

	"google.golang.org/grpc"
	"google.golang.org/grpc/metadata"
)

type traceCtxKey struct{}

// TraceUnaryClientInterceptor внедряет traceparent в исходящие gRPC метаданные.
func TraceUnaryClientInterceptor() grpc.UnaryClientInterceptor {
	return func(
		ctx context.Context,
		method string,
		req, reply interface{},
		cc *grpc.ClientConn,
		invoker grpc.UnaryInvoker,
		opts ...grpc.CallOption,
	) error {
		traceParent, ok := ctx.Value(traceCtxKey{}).(string)
		if ok && traceParent != "" {
			// Добавляем traceparent в gRPC outgoing metadata
			md, exists := metadata.FromOutgoingContext(ctx)
			if !exists {
				md = metadata.New(nil)
			} else {
				md = md.Copy()
			}
			md.Set("traceparent", traceParent)
			ctx = metadata.NewOutgoingContext(ctx, md)
			log.Printf("[gRPC Client Interceptor] Injected traceparent: %s into RPC %s", traceParent, method)
		}
		return invoker(ctx, method, req, reply, cc, opts...)
	}
}

// TraceUnaryServerInterceptor извлекает traceparent из входящих gRPC метаданных.
func TraceUnaryServerInterceptor() grpc.UnaryServerInterceptor {
	return func(
		ctx context.Context,
		req interface{},
		info *grpc.UnaryServerInfo,
		handler grpc.UnaryHandler,
	) (interface{}, error) {
		md, ok := metadata.FromIncomingContext(ctx)
		var traceParent string
		if ok {
			vals := md.Get("traceparent")
			if len(vals) > 0 {
				traceParent = vals[0]
				log.Printf("[gRPC Server Interceptor] Extracted traceparent: %s in method %s", traceParent, info.FullMethod)
			}
		}

		if traceParent == "" {
			traceParent = "00-default-generated-trace-id-01"
		}

		// Помещаем в контекст обработчика
		ctxWithTrace := context.WithValue(ctx, traceCtxKey{}, traceParent)
		return handler(ctxWithTrace, req)
	}
}

func main() {
	clientInterceptor := TraceUnaryClientInterceptor()
	serverInterceptor := TraceUnaryServerInterceptor()
	_ = clientInterceptor
	_ = serverInterceptor

	fmt.Println("gRPC Unary Client and Server metadata trace interceptors verified")
}

package main

import (
	"context"
	"errors"
	"fmt"
	"log"
	"time"

	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/attribute"
	"go.opentelemetry.io/otel/codes"
	"go.opentelemetry.io/otel/trace"
)

// ExecuteDatabaseQuery демонстрирует эталонную инструментацию спана OTel.
func ExecuteDatabaseQuery(ctx context.Context, query string, userID int) error {
	tracer := otel.Tracer("order-repository")

	// 1. Создаем спан с семантическим именем операции
	ctx, span := tracer.Start(ctx, "DB Query: FetchOrders",
		trace.WithSpanKind(trace.SpanKindClient),
	)
	defer span.End() // Гарантированное завершение спана и фиксация длительности

	// 2. Добавляем стандартизированные атрибуты (OpenTelemetry Semantic Conventions)
	span.SetAttributes(
		attribute.String("db.system", "postgresql"),
		attribute.String("db.name", "orders_db"),
		attribute.String("db.statement", query),
		attribute.Int("app.user_id", userID),
	)

	// Имитация выполнения SQL запроса
	time.Sleep(25 * time.Millisecond)

	// 3. Симуляция ошибки и фиксация в телеметрии
	if userID < 0 {
		err := errors.New("sql: invalid user_id constraint violation")

		// Записываем событие ошибки
		span.RecordError(err)

		// Устанавливаем статус ошибки спана для подсветки в Jaeger
		span.SetStatus(codes.Error, err.Error())
		return err
	}

	span.SetStatus(codes.Ok, "query succeeded")
	return nil
}

func main() {
	ctx := context.Background()

	log.Println("Executing tracked database span with OpenTelemetry...")
	err := ExecuteDatabaseQuery(ctx, "SELECT * FROM orders WHERE user_id = $1", 42)
	if err != nil {
		log.Printf("Query failed: %v", err)
	}

	fmt.Println("Manual OpenTelemetry Span with attributes and status verified")
}

package main

import (
	"context"
	"fmt"
	"log"
	"time"

	"google.golang.org/grpc"
	"google.golang.org/grpc/credentials/insecure"
)

// InitRoundRobinGRPCClient настраивает клиентскую балансировку по всем подам с реакцией на GOAWAY.
func InitRoundRobinGRPCClient(serviceTarget string) (*grpc.ClientConn, error) {
	// Конфигурация встроенного клиентского балансировщика Round Robin
	roundRobinServiceConfig := `{
		"loadBalancingConfig": [{"round_robin": {}}],
		"methodConfig": [{
			"name": [{"service": ""}],
			"retryPolicy": {
				"maxAttempts": 3,
				"initialBackoff": "0.1s",
				"maxBackoff": "1s",
				"backoffMultiplier": 2.0,
				"retryableStatusCodes": ["UNAVAILABLE"]
			}
		}]
	}`

	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()

	log.Printf("[gRPC Client LB] Dialing %s with DNS resolver & Round-Robin...", serviceTarget)
	conn, err := grpc.DialContext(ctx, serviceTarget,
		grpc.WithTransportCredentials(insecure.NewCredentials()),
		grpc.WithDefaultServiceConfig(roundRobinServiceConfig),
	)
	if err != nil {
		return nil, fmt.Errorf("dial failed: %w", err)
	}

	return conn, nil
}

func main() {
	// Пример адреса Headless Service: dns:///order-service.default.svc.cluster.local:50051
	conn, err := InitRoundRobinGRPCClient("dns:///localhost:50051")
	if err != nil {
		log.Printf("Dial failed: %v", err)
		return
	}
	defer conn.Close()

	fmt.Println("gRPC Client-side Round-Robin balancer with GOAWAY draining support initialized")
}

package main

import (
	"context"
	"fmt"
	"log"
	"time"

	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/attribute"
	"go.opentelemetry.io/otel/trace"
)

func ValidateCart(ctx context.Context) {
	tracer := otel.Tracer("order-service")
	_, span := tracer.Start(ctx, "ValidateCart")
	defer span.End()

	time.Sleep(10 * time.Millisecond)
	span.SetAttributes(attribute.Bool("cart.valid", true))
}

func ChargePayment(ctx context.Context, amount float64) {
	tracer := otel.Tracer("payment-service")
	_, span := tracer.Start(ctx, "ChargePayment",
		trace.WithSpanKind(trace.SpanKindClient),
	)
	defer span.End()

	time.Sleep(30 * time.Millisecond)
	span.SetAttributes(attribute.Float64("payment.amount", amount))
}

func ReserveStock(ctx context.Context, itemID string) {
	tracer := otel.Tracer("warehouse-service")
	_, span := tracer.Start(ctx, "ReserveStock")
	defer span.End()

	time.Sleep(15 * time.Millisecond)
	span.SetAttributes(attribute.String("warehouse.item_id", itemID))
}

// ProcessOrder координирует бизнес-процесс и создает дерево вложенных спанов.
func ProcessOrder(ctx context.Context, orderID string) {
	tracer := otel.Tracer("order-coordinator")
	ctx, rootSpan := tracer.Start(ctx, "ProcessOrder")
	defer rootSpan.End()

	rootSpan.SetAttributes(attribute.String("order.id", orderID))

	log.Printf("[Trace Root] Starting ProcessOrder under TraceID: %s", rootSpan.SpanContext().TraceID())

	// Передаем ctx дальше — дочерние спаны автоматически унаследуют ParentSpanID
	ValidateCart(ctx)
	ChargePayment(ctx, 199.90)
	ReserveStock(ctx, "sku-laptop-x1")

	log.Println("[Trace Root] ProcessOrder successfully completed with all child spans")
}

func main() {
	ProcessOrder(context.Background(), "ord-8831")
	fmt.Println("Nested spans with parent-child relationships verified successfully")
}

package main

import (
	"context"
	"fmt"
	"log"
	"net/http"
	"os"
	"os/signal"
	"sync/atomic"
	"syscall"
	"time"
)

var isDraining int32

// HealthCheckHandler сигнализирует Kubernetes о готовности пода принимать трафик.
func HealthCheckHandler(w http.ResponseWriter, r *http.Request) {
	if atomic.LoadInt32(&isDraining) == 1 {
		// При перехвате SIGTERM возвращаем 503, ускоряя исключение пода из балансировки
		http.Error(w, "Pod is draining", http.StatusServiceUnavailable)
		return
	}
	w.WriteHeader(http.StatusOK)
	w.Write([]byte("ready"))
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("/readyz", HealthCheckHandler)
	mux.HandleFunc("/api/work", func(w http.ResponseWriter, r *http.Request) {
		w.Write([]byte(`{"status":"success"}`))
	})

	srv := &http.Server{
		Addr:    ":8080",
		Handler: mux,
	}

	sigChan := make(chan os.Signal, 1)
	signal.Notify(sigChan, syscall.SIGTERM, syscall.SIGINT)

	go func() {
		log.Println("Service running on :8080...")
		if err := srv.ListenAndServe(); err != nil && err != http.ErrServerClosed {
			log.Fatalf("Server listen error: %v", err)
		}
	}()

	<-sigChan
	log.Println("[K8s Shutdown] Received SIGTERM! Phase 1: Marking Readiness as 503...")
	atomic.StoreInt32(&isDraining, 1)

	// КРИТИЧЕСКАЯ ЗАДЕРЖКА: даем kube-proxy и Ingress время обновить iptables роуты
	drainWait := 5 * time.Second
	log.Printf("[K8s Shutdown] Phase 2: Sleeping %v while continuing to serve active traffic...", drainWait)
	time.Sleep(drainWait)

	log.Println("[K8s Shutdown] Phase 3: Now safe to invoke srv.Shutdown()...")
	shutdownCtx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()

	if err := srv.Shutdown(shutdownCtx); err != nil {
		log.Fatalf("Shutdown failed: %v", err)
	}
	fmt.Println("Zero-downtime Kubernetes pod termination sequence completed successfully")
}

package main

import (
	"context"
	"fmt"
	"log"

	sdktrace "go.opentelemetry.io/otel/sdk/trace"
	"go.opentelemetry.io/otel/trace"
)

// InitSampledTracerProvider настраивает вероятностный семплинг 10% с уважением к родительским трейсам.
func InitSampledTracerProvider(ratio float64) *sdktrace.TracerProvider {
	// ParentBased гарантирует: если родительский сервис решил семплировать запрос,
	// текущий сервис обязательно продолжит запись трейса, сохраняя целостность графа.
	sampler := sdktrace.ParentBased(
		sdktrace.TraceIDRatioBased(ratio),
	)

	tp := sdktrace.NewTracerProvider(
		sdktrace.WithSampler(sampler),
	)
	return tp
}

func main() {
	ratio := 0.10 // 10%
	tp := InitSampledTracerProvider(ratio)
	tracer := tp.Tracer("sampling-demo")

	totalRequests := 1000
	sampledCount := 0

	for i := 0; i < totalRequests; i++ {
		// Создаем корневой спан
		_, span := tracer.Start(context.Background(), "HTTP Request")
		sc := span.SpanContext()
		if sc.IsSampled() {
			sampledCount++
		}
		span.End()
	}

	actualRatio := float64(sampledCount) / float64(totalRequests) * 100.0
	log.Printf("Total Spans: %d, Sampled Spans: %d (Actual: %.1f%%, Target: %.1f%%)",
		totalRequests, sampledCount, actualRatio, ratio*100.0)

	fmt.Println("TraceIDRatioBased probabilistic sampling verified successfully")
}

package main

import (
	"context"
	"errors"
	"fmt"
	"log"
	"net/http"
	"os"
	"os/signal"
	"sync/atomic"
	"syscall"
	"time"
)

type ServerApp struct {
	httpServer *http.Server
	isDraining atomic.Bool
}

func NewServerApp(addr string) *ServerApp {
	app := &ServerApp{}
	mux := http.NewServeMux()

	mux.HandleFunc("/healthz", func(w http.ResponseWriter, r *http.Request) {
		if app.isDraining.Load() {
			http.Error(w, "shutting down, draining traffic", http.StatusServiceUnavailable)
			return
		}
		w.WriteHeader(http.StatusOK)
		_, _ = w.Write([]byte("OK"))
	})

	mux.HandleFunc("/api/work", func(w http.ResponseWriter, r *http.Request) {
		time.Sleep(100 * time.Millisecond)
		w.WriteHeader(http.StatusOK)
		_, _ = w.Write([]byte(`{"status":"processed"}`))
	})

	app.httpServer = &http.Server{
		Addr:    addr,
		Handler: mux,
	}
	return app
}

func (app *ServerApp) Run() error {
	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()

	errChan := make(chan error, 1)
	go func() {
		log.Printf("Server listening on %s", app.httpServer.Addr)
		if err := app.httpServer.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {
			errChan <- err
		}
	}()

	select {
	case err := <-errChan:
		return fmt.Errorf("server error: %w", err)
	case <-ctx.Done():
		log.Println("[SIGTERM] Received termination signal, starting graceful draining...")
	}

	// 1. Помечаем под как не готовый принимать трафик
	app.isDraining.Store(true)

	// 2. Выдерживаем задержку для распространения изменений iptables/IPVS в K8s
	drainDelay := 2 * time.Second
	log.Printf("[Drain] Sleeping %v to allow K8s endpoints and kube-proxy to propagate...", drainDelay)
	time.Sleep(drainDelay)

	// 3. Завершаем активные запросы через server.Shutdown
	shutdownCtx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()

	log.Println("[Shutdown] Closing listeners and draining remaining in-flight requests...")
	if err := app.httpServer.Shutdown(shutdownCtx); err != nil {
		return fmt.Errorf("graceful shutdown failed: %w", err)
	}

	log.Println("[Shutdown] Server gracefully stopped without packet loss.")
	return nil
}

func main() {
	app := NewServerApp(":8080")
	if err := app.Run(); err != nil {
		log.Fatalf("Server exit with error: %v", err)
	}
}

